  9	import com.pousadamarealta.repository.ReservationRepository;
 10	import com.pousadamarealta.repository.RoomRepository;
 11	import com.pousadamarealta.service.MessageService;
 12	import com.pousadamarealta.service.PricingService;
 13	import com.pousadamarealta.service.ReportService;
 14	import com.pousadamarealta.service.ReservationService;
 15	import com.zaxxer.hikari.HikariConfig;
 16	import com.zaxxer.hikari.HikariDataSource;
 17	import io.javalin.Javalin;
 18	import io.javalin.json.JavalinJackson;
 19	
 20	import javax.sql.DataSource;
 21	
 22	public class App {
 23	    public static void main(String[] args) {
 24	        String dbUrl = System.getenv("DB_URL");
 25	        String dbUser = System.getenv("DB_USER");
 26	        String dbPassword = System.getenv("DB_PASSWORD");
 27	        String portStr = System.getenv("PORT");
 28	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 29	
 30	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 31	            throw new IllegalStateException("Database configuration not provided");
 32	        }
 33	
 34	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 35	
 36	        DataSource dataSource = createDataSource(dbUrl, dbUser, dbPassword);
 37	
 38	        DatabaseSetup dbSetup = new DatabaseSetup(dataSource);
 39	        dbSetup.initialize();
 40	
 41	        RoomRepository roomRepository = new RoomRepository(dataSource);
 42	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 43	        MessageRepository messageRepository = new MessageRepository(dataSource);
 44	
 45	        PricingService pricingService = new PricingService();
 46	        MessageService messageService = new MessageService(messageRepository, testMode, !testMode);
 47	        ReservationService reservationService = new ReservationService(
 48	            reservationRepository,
 49	            roomRepository,
 50	            pricingService,
 51	            messageService
 52	        );
 53	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 54	
 55	        ApiController controller = new ApiController(
 56	            roomRepository,
 57	            reservationService,
 58	            messageRepository,
 59	            reportService
 60	        );
 61	
 62	        ObjectMapper objectMapper = new ObjectMapper()
 63	            .registerModule(new JavaTimeModule())
 64	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 65	
 66	        Javalin app = Javalin.create(config -> {
 67	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 68	        });
 69	
 70	        app.get("/rooms", controller::getRooms);
 71	        app.post("/reservations", controller::createReservation);
 72	        app.get("/reservations/{id}", controller::getReservation);
 73	        app.post("/reservations/{id}/confirmation", controller::confirmReservation);
 74	        app.post("/reservations/{id}/cancellation", controller::cancelReservation);
 75	        app.post("/reservations/{id}/check-in", controller::checkInReservation);
 76	        app.post("/reservations/{id}/check-out", controller::checkOutReservation);
 77	        app.get("/reservations/{id}/document", controller::getDocument);
 78	        app.get("/messages", controller::getMessages);
 79	        app.get("/reports/occupancy", controller::getOccupancyReport);
 80	        app.get("/reports/revenue", controller::getRevenueReport);
 81	
 82	        app.start(port);
 83	        System.out.println("Server started on port " + port);
 84	    }
 85	
 86	    private static DataSource createDataSource(String url, String user, String password) {
 87	        HikariConfig config = new HikariConfig();
 88	        config.setJdbcUrl(url);
 89	        config.setUsername(user);
 90	        config.setPassword(password);
 91	        config.setMaximumPoolSize(10);
 92	        return new HikariDataSource(config);
 93	    }
 94	}
