137	    public void createReservation(Context ctx) {
138	        try {
139	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
140	
141	            if (request.roomNumber() == null || request.guestName() == null ||
142	                request.guestEmail() == null || request.guestCpf() == null ||
143	                request.checkIn() == null || request.checkOut() == null ||
144	                request.ratePlan() == null) {
145	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
146	                return;
147	            }
148	
149	            Reservation reservation = reservationService.createReservation(
150	                request.roomNumber(),
151	                request.guestName(),
152	                request.guestEmail(),
153	                request.guestCpf(),
154	                request.checkIn(),
155	                request.checkOut(),
156	                request.guests(),
157	                request.ratePlan()
158	            );
159	
160	            ctx.status(201).json(ReservationResponse.from(reservation));
161	        } catch (InvalidRequestException e) {
162	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
163	        } catch (RoomNotFoundException e) {
164	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
165	        } catch (RoomUnavailableException e) {
166	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
167	        } catch (CapacityExceededException e) {
168	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
169	        } catch (Exception e) {
170	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
171	        }
172	    }
