267	    public void getOccupancyReport(Context ctx) {
268	        try {
269	            String dateParam = ctx.queryParam("date");
270	            if (dateParam == null) {
271	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
272	                return;
273	            }
274	
275	            LocalDate date = LocalDate.parse(dateParam);
276	            String csv = reportService.generateOccupancyReport(date);
277	            ctx.contentType("text/csv; charset=utf-8").result(csv);
278	        } catch (DateTimeParseException e) {
279	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
280	        }
281	    }
282	
283	    public void getRevenueReport(Context ctx) {
284	        try {
285	            String monthParam = ctx.queryParam("month");
286	            if (monthParam == null) {
287	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
288	                return;
289	            }
290	
291	            YearMonth month = YearMonth.parse(monthParam);
292	            String csv = reportService.generateRevenueReport(month);
293	            ctx.contentType("text/csv; charset=utf-8").result(csv);
294	        } catch (DateTimeParseException e) {
295	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
296	        }
297	    }
298	}

