122	import com.pousadamarealta.domain.RatePlan;
123	
124	import java.math.BigDecimal;
125	import java.math.RoundingMode;
126	import java.time.LocalDate;
127	import java.time.Month;
128	
129	public final class PricingService {
130	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
131	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
132	
133	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
134	        if (isHighSeason(night)) {
135	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
136	        }
137	        return baseRate;
138	    }
139	
140	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
141	        BigDecimal subtotal = BigDecimal.ZERO;
142	        LocalDate current = checkIn;
143	
144	        while (current.isBefore(checkOut)) {
145	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
146	            subtotal = subtotal.add(nightPrice);
147	            current = current.plusDays(1);
148	        }
149	
150	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
151	    }
152	
153	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
154	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
155	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
156	        }
157	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
158	    }
159	
160	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
161	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
162	    }
163	
164	    private boolean isHighSeason(LocalDate date) {
165	        Month month = date.getMonth();
166	        int day = date.getDayOfMonth();
167	
168	        // Julho inteiro
169	        if (month == Month.JULY) {
170	            return true;
171	        }
172	
173	        // Dezembro a partir do dia 15
174	        if (month == Month.DECEMBER && day >= 15) {
175	            return true;
176	        }
177	
178	        // Janeiro e fevereiro inteiros
179	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
180	            return true;
181	        }
182	
183	        return false;
184	    }
185	}
