199	public final class ReportService {
200	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
201	
202	    private final ReservationRepository reservationRepository;
203	    private final RoomRepository roomRepository;
204	
205	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
206	        this.reservationRepository = reservationRepository;
207	        this.roomRepository = roomRepository;
208	    }
209	
210	    public String generateOccupancyReport(LocalDate night) {
211	        List<Reservation> reservations = reservationRepository.findByNight(night);
212	        List<Room> allRooms = roomRepository.findAll();
213	
214	        StringBuilder csv = new StringBuilder();
215	        csv.append("room,type,reservation,check_in,check_out\n");
216	
217	        for (Reservation reservation : reservations) {
218	            csv.append(reservation.getRoomNumber()).append(",");
219	
220	            Room room = allRooms.stream()
221	                .filter(r -> r.number().equals(reservation.getRoomNumber()))
222	                .findFirst()
223	                .orElseThrow();
224	
225	            csv.append(room.type()).append(",");
226	            csv.append(reservation.getId()).append(",");
227	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
228	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
229	        }
230	
231	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
232	
233	        return csv.toString();
234	    }
235	
236	    public String generateRevenueReport(YearMonth month) {
237	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
238	
239	        StringBuilder csv = new StringBuilder();
240	        csv.append("reservation,room,check_in,check_out,status,amount\n");
241	
242	        BigDecimal totalRevenue = BigDecimal.ZERO;
243	
244	        for (Reservation reservation : reservations) {
245	            BigDecimal retained = reservation.getAmountRetained();
246	            if (retained.compareTo(BigDecimal.ZERO) > 0) {
247	                csv.append(reservation.getId()).append(",");
248	                csv.append(reservation.getRoomNumber()).append(",");
249	                csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
250	                csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
251	                csv.append(reservation.getStatus()).append(",");
252	                csv.append(formatDecimal(retained)).append("\n");
253	
254	                totalRevenue = totalRevenue.add(retained);
255	            }
256	        }
257	
258	        csv.append("total,").append(formatDecimal(totalRevenue));
259	
260	        return csv.toString();
261	    }
262	
263	    private String formatDecimal(BigDecimal value) {
264	        return value.toString().replace(",", ".");
265	    }
