267	package com.pousadamarealta.service;
268	
269	import com.pousadamarealta.domain.*;
270	import com.pousadamarealta.repository.ReservationRepository;
271	import com.pousadamarealta.repository.RoomRepository;
272	
273	import java.math.BigDecimal;
274	import java.time.LocalDate;
275	import java.time.temporal.ChronoUnit;
276	
277	public final class ReservationService {
278	    private final ReservationRepository reservationRepository;
279	    private final RoomRepository roomRepository;
280	    private final PricingService pricingService;
281	    private final MessageService messageService;
282	
283	    public ReservationService(
284	        ReservationRepository reservationRepository,
285	        RoomRepository roomRepository,
286	        PricingService pricingService,
287	        MessageService messageService
288	    ) {
289	        this.reservationRepository = reservationRepository;
290	        this.roomRepository = roomRepository;
291	        this.pricingService = pricingService;
292	        this.messageService = messageService;
293	    }
294	
295	    public Reservation createReservation(
296	        String roomNumber,
297	        String guestName,
298	        String guestEmail,
299	        String guestCpf,
300	        LocalDate checkIn,
301	        LocalDate checkOut,
302	        int guests,
303	        RatePlan ratePlan
304	    ) {
305	        Room room = roomRepository.findByNumber(roomNumber)
306	            .orElseThrow(() -> new RoomNotFoundException());
307	
308	        if (guests < 1) {
309	            throw new InvalidRequestException("Number of guests must be at least 1");
310	        }
311	
312	        if (guests > room.capacity()) {
313	            throw new CapacityExceededException();
314	        }
315	
316	        if (!checkOut.isAfter(checkIn)) {
317	            throw new InvalidRequestException("Check-out must be after check-in");
318	        }
319	
320	        if (reservationRepository.hasConflictingReservation(roomNumber, checkIn, checkOut, null)) {
321	            throw new RoomUnavailableException();
322	        }
323	
324	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
325	        BigDecimal subtotal = pricingService.calculateSubtotal(room.nightlyRate(), checkIn, checkOut);
326	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
327	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
328	
329	        Reservation reservation = new Reservation(
330	            null,
331	            roomNumber,
332	            guestName,
333	            guestEmail,
334	            guestCpf,
335	            checkIn,
336	            checkOut,
337	            guests,
338	            ratePlan,
339	            nights,
340	            subtotal,
341	            discount,
342	            total,
343	            ReservationStatus.PENDING,
344	            BigDecimal.ZERO,
345	            null
346	        );
347	
348	        return reservationRepository.save(reservation);
349	    }
350	
351	    public Reservation confirm(Long id) {
352	        Reservation reservation = getReservation(id);
353	
354	        if (reservation.getStatus() != ReservationStatus.PENDING) {
355	            throw new OperationNotAllowedException();
356	        }
357	
358	        reservation.setStatus(ReservationStatus.CONFIRMED);
359	        reservation.setAmountPaid(reservation.getTotal());
360	        reservationRepository.save(reservation);
361	
362	        ReservationDocument document = createDocument(reservation);
363	        messageService.sendReservationConfirmation(reservation, document);
364	
365	        return reservation;
366	    }
367	
368	    public Reservation cancel(Long id) {
369	        Reservation reservation = getReservation(id);
370	
371	        if (reservation.getStatus() != ReservationStatus.PENDING &&
372	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
373	            throw new OperationNotAllowedException();
374	        }
375	
376	        reservation.setStatus(ReservationStatus.CANCELLED);
377	
378	        BigDecimal refundAmount = BigDecimal.ZERO;
379	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
380	            refundAmount = reservation.getAmountPaid();
381	        }
382	
383	        if (refundAmount.compareTo(BigDecimal.ZERO) > 0) {
384	            reservation.setRefund(refundAmount);
385	        } else {
386	            reservation.setRefund(BigDecimal.ZERO);
387	        }
388	
389	        reservationRepository.save(reservation);
390	        return reservation;
391	    }
392	
393	    public Reservation checkIn(Long id) {
394	        Reservation reservation = getReservation(id);
395	
396	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
397	            throw new OperationNotAllowedException();
398	        }
399	
400	        reservation.setStatus(ReservationStatus.CHECKED_IN);
401	        reservationRepository.save(reservation);
402	        return reservation;
403	    }
404	
405	    public Reservation checkOut(Long id) {
406	        Reservation reservation = getReservation(id);
407	
408	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
409	            throw new OperationNotAllowedException();
410	        }
411	
412	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
413	        reservationRepository.save(reservation);
414	        return reservation;
415	    }
416	
417	    public Reservation getReservation(Long id) {
418	        return reservationRepository.findById(id)
419	            .orElseThrow(() -> new ReservationNotFoundException());
420	    }
421	
422	    public ReservationDocument createDocument(Reservation reservation) {
423	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
424	            .orElseThrow(() -> new RoomNotFoundException());
425	
426	        return new ReservationDocument(
427	            "Comprovante de reserva",
428	            reservation.getId(),
429	            reservation.getGuestName(),
430	            reservation.getGuestCpf(),
431	            reservation.getRoomNumber(),
432	            room.type(),
433	            reservation.getCheckIn(),
434	            reservation.getCheckOut(),
435	            reservation.getNights(),
436	            reservation.getSubtotal(),
437	            reservation.getDiscount(),
438	            reservation.getTotal()
439	        );
440	    }
441	
442	    public static class RoomNotFoundException extends RuntimeException {}
443	    public static class ReservationNotFoundException extends RuntimeException {}
444	    public static class RoomUnavailableException extends RuntimeException {}
445	    public static class CapacityExceededException extends RuntimeException {}
446	    public static class OperationNotAllowedException extends RuntimeException {}
447	    public static class InvalidRequestException extends RuntimeException {
448	        public InvalidRequestException(String message) {
449	            super(message);
450	        }
451	    }
452	}

