 81	    }
 82	
 83	    public Reservation save(Reservation reservation) {
 84	        if (reservation.getId() == null) {
 85	            return insert(reservation);
 86	        } else {
 87	            update(reservation);
 88	            return reservation;
 89	        }
 90	    }
