 92	    private Reservation insert(Reservation reservation) {
 93	        String sql = """
 94	            INSERT INTO reservations (
 95	                room_number, guest_name, guest_email, guest_cpf,
 96	                check_in, check_out, guests, rate_plan,
 97	                nights, subtotal, discount, total, status, amount_paid, refund
 98	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 99	            RETURNING id
100	        """;
101	
102	        try (Connection conn = dataSource.getConnection();
103	             PreparedStatement stmt = conn.prepareStatement(sql)) {
104	
105	            setReservationParams(stmt, reservation);
106	
107	            try (ResultSet rs = stmt.executeQuery()) {
108	                if (rs.next()) {
109	                    long id = rs.getLong(1);
110	                    return new Reservation(
111	                        id,
112	                        reservation.getRoomNumber(),
113	                        reservation.getGuestName(),
114	                        reservation.getGuestEmail(),
115	                        reservation.getGuestCpf(),
116	                        reservation.getCheckIn(),
117	                        reservation.getCheckOut(),
118	                        reservation.getGuests(),
119	                        reservation.getRatePlan(),
120	                        reservation.getNights(),
121	                        reservation.getSubtotal(),
122	                        reservation.getDiscount(),
123	                        reservation.getTotal(),
124	                        reservation.getStatus(),
125	                        reservation.getAmountPaid(),
126	                        reservation.getRefund()
127	                    );
128	                }
129	                throw new RuntimeException("Failed to get generated ID");
130	            }
131	        } catch (SQLException e) {
132	            throw new RuntimeException("Failed to insert reservation", e);
133	        }
134	    }
135	
136	    private void update(Reservation reservation) {
137	        String sql = """
138	            UPDATE reservations SET
139	                status = ?, amount_paid = ?, refund = ?
140	            WHERE id = ?
141	        """;
142	
143	        try (Connection conn = dataSource.getConnection();
144	             PreparedStatement stmt = conn.prepareStatement(sql)) {
145	
146	            stmt.setString(1, reservation.getStatus().name());
147	            stmt.setBigDecimal(2, reservation.getAmountPaid());
148	            stmt.setBigDecimal(3, reservation.getRefund());
149	            stmt.setLong(4, reservation.getId());
150	
151	            stmt.executeUpdate();
152	        } catch (SQLException e) {
153	            throw new RuntimeException("Failed to update reservation", e);
154	        }
155	    }
