163	        stmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
164	        stmt.setInt(7, reservation.getGuests());
165	        stmt.setString(8, reservation.getRatePlan().name());
166	        stmt.setInt(9, reservation.getNights());
167	        stmt.setBigDecimal(10, reservation.getSubtotal());
168	        stmt.setBigDecimal(11, reservation.getDiscount());
169	        stmt.setBigDecimal(12, reservation.getTotal());
170	        stmt.setString(13, reservation.getStatus().name());
171	        stmt.setBigDecimal(14, reservation.getAmountPaid());
172	        stmt.setBigDecimal(15, reservation.getRefund());
173	    }
