191	    public boolean hasConflictingReservation(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
192	        String sql = """
193	            SELECT COUNT(*) FROM reservations
194	            WHERE room_number = ?
195	              AND status != 'CANCELLED'
196	              AND check_in < ?
197	              AND check_out > ?
198	              AND (? IS NULL OR id != ?)
199	        """;
200	
201	        try (Connection conn = dataSource.getConnection();
202	             PreparedStatement stmt = conn.prepareStatement(sql)) {
203	
204	            stmt.setString(1, roomNumber);
205	            stmt.setDate(2, Date.valueOf(checkOut));
206	            stmt.setDate(3, Date.valueOf(checkIn));
207	            stmt.setObject(4, excludeId);
208	            stmt.setObject(5, excludeId);
209	
210	            try (ResultSet rs = stmt.executeQuery()) {
211	                return rs.next() && rs.getInt(1) > 0;
212	            }
213	        } catch (SQLException e) {
214	            throw new RuntimeException("Failed to check conflicts", e);
215	        }
